import { moduleNotation } from '../asn1/notation';
import { BasicSafetyMessage, CLASS_ASSIGNMENTS, MessageFrame } from './schema';

export const MODULE_NAME = 'V2XMessageLab-BSM-PartI';

/**
 * ASN.1 module text generated from the encoder's own schema objects.
 * This is NOT the official SAE J2735 ASN.1 module (an SAE product, J2735ASN_202409);
 * it is a minimal, independently written subset sufficient for BSM Part I.
 */
export function bsmModuleText(): string {
  return moduleNotation({
    name: MODULE_NAME,
    header: [
      '-- Generated by V2X Message Lab from its internal schema (src/j2735/schema).',
      '-- Minimal subset of SAE J2735 (SEP2024) structures needed for BSM Part I.',
      '-- Not the official SAE ASN.1 module. Part II and regional values are open types',
      '-- whose object sets are left empty (their contents are not modelled).',
    ].join('\n'),
    roots: [MessageFrame, BasicSafetyMessage],
    extraAssignments: CLASS_ASSIGNMENTS,
  });
}
